/**
 * The ParamorphicConcept Unit (owner's ruling, 2026-11-19) —
 * a unit inside the Ontology Knowledge Unit (OKU) holding the
 * paramorphic concepts: the generic abstract structures of the
 * paramorphic-components framework, each a family generated by
 * a declared parameter set — one concept, moved along its
 * parameters, yields its variants while keeping its identity.
 *
 * Placement (owner's ruling, 2026-11-19, in the Paramorphic
 * Theory chat): all paramorphic concepts are in a
 * ParamorphicConcept Unit in the OKU. The rulings taken with
 * it ("rec", 2026-11-19):
 *
 *  1. The unit holds the GENERIC CONCEPTS and their shared
 *     operations. The system's existing structures — the
 *     correspondence graph, the parser's meaning graph, the
 *     WordNet climb, the Luoshu — are INSTANCES of these
 *     concepts and stay where they live, referenced here as
 *     instances. Nothing is moved, and nothing in this module
 *     re-expresses them.
 *  2. The contents are CLOSED at the six concepts of the
 *     paramorphic-components record: Grid, Graph, Tree, Path,
 *     Protocol, Logic. Network is not a seventh concept (it
 *     folds into Graph topology + Protocol transport, as that
 *     record ruled); Timeline and Spatial Structures were
 *     named there but never developed. Adding a concept is
 *     the owner's ruling, not a registration.
 *  3. This first slice is the ProblemSolving placeholder
 *     shape: the seat on the map, the placeholder, and the
 *     concepts registered AS DATA — the way the classification
 *     table registers entries and problem-solving.ts registers
 *     approach graphs. NO ENGINE: no operation named here
 *     runs, no walk is walked by this unit, and no consumer
 *     is rewired. Engines are later slices of their own.
 *
 * What a concept entry holds: its substrate (what the concept
 * is made of, in the components record's terms), its
 * parameters (the directions it can be moved in — derived
 * from the AnSci specimens named as instances, not designed
 * in the abstract), its shared operations (the vocabulary of
 * what is done with structures of this kind across the
 * system, registered as names and glosses), its AnSci
 * instances (each with where it lives today), and its
 * invariants (what a parameter move may never do).
 *
 * The standing invariant, carried over from the one earlier
 * entry of paramorphic theory into this system
 * (docs/design-conversation-engine.md § Morphs: an invariant
 * core never morphs): moving a concept along a parameter may
 * generate a DERIVED candidate; it may never rewrite a filed
 * row in the classification table or the correspondence
 * graph, and never upgrade a provenance tier. Attestation
 * does not morph.
 */

export const PARAMORPHIC_CONCEPT_UNIT = "ontology-core/ontology-knowledge-unit/paramorphic-concept-unit";

/* ------------------------------------------------------------------ */
/* The concept registry                                                 */
/* ------------------------------------------------------------------ */

export type ParamorphicConceptId = "grid" | "graph" | "tree" | "path" | "protocol" | "logic";

/** An existing structure of the system, recognised as an
 *  instance of a concept. The instance stays where it lives;
 *  `where` is its address (a file, or a schematic address). */
export interface ConceptInstance {
  name: string;
  where: string;
  standing: string;
}

export interface ParamorphicConcept {
  id: ParamorphicConceptId;
  name: string;
  /** What the concept is made of (the components record's substrate). */
  substrate: string;
  /** The directions the concept can be moved in. */
  parameters: string[];
  /** Shared operations over structures of this kind, as a
   *  registered vocabulary — names and glosses only; no
   *  engine runs them at this grade. */
  sharedOperations: { name: string; gloss: string }[];
  /** The system's existing instances, left in place. Empty
   *  where the system has no specimen yet — the absence is
   *  the record, stated in `specimenStanding`. */
  instances: ConceptInstance[];
  /** Where the concept's specimens stand in AnSci today. */
  specimenStanding: string;
  /** What a parameter move may never do to this concept. */
  invariants: string[];
}

