/** A concept by id ("grid", "graph", …), when registered.
 *  The list is closed (owner's ruling, 2026-11-19): an
 *  unregistered id is not an oversight to patch but a
 *  concept the unit does not hold. */
export function conceptById(id: string): ParamorphicConcept | undefined {
  return PARAMORPHIC_CONCEPTS.find((c) => c.id === id);
}
